def _dense(bars):
    """하루당 봉 밀도 충분? (부분일 몇 봉만 온 경우 배제)."""
    nd = len({b.day for b in bars})
    return bool(bars) and (not nd or len(bars) / max(nd, 1) >= MIN_BARS_PER_DAY)


def bars_5m(code, start, end):
    """이번 주 5분봉. tvDatafeed 메인 → 부실하면 yfinance. 반환: (bars, source).

    yfinance는 KRX에서 부실(간혹 1봉)해, 예전엔 'tv보다 많으면 무조건' 대체하던 로직이
    빈 tv를 1봉짜리로 덮어 0%·0진입 오보를 냈다(2026-07-13 036930). → yfinance는
    최소봉수(MIN_WEEK_BARS) 넘고 tv보다 길 때만 대체. 둘 다 최소치 미만이면 source='부실'로 신호."""
    tv = _bars_tv(code, start, end)
    if len(tv) >= MIN_WEEK_BARS and _dense(tv):
        return tv, "tvDatafeed"
    yb = _bars_yf(code, start, end)
    if len(yb) >= MIN_WEEK_BARS and len(yb) > len(tv):
        return yb, "yfinance(fallback)"
    best = tv if len(tv) >= len(yb) else yb
    if len(best) >= MIN_WEEK_BARS:
        return best, ("tvDatafeed" if best is tv else "yfinance(fallback)")
    return best, ("부실" if best else "없음")

